const fs=require("fs");const path=require("path");
const base=process.env.HOME+"/.claude/projects";
const key=process.env.OPENROUTER_API_KEY||"";
const dirs=fs.readdirSync(base).filter(d=>d.startsWith("-home-walter-Github-chiri-ai-editor"));
const walk=d=>fs.readdirSync(d,{withFileTypes:true}).flatMap(e=>e.isDirectory()?walk(path.join(d,e.name)):[path.join(d,e.name)]);
const re=/sk-or-[A-Za-z0-9](?:[A-Za-z0-9._-]*[A-Za-z0-9_-])?/g;
const stats={};let exact=0;let hex64=0;
for(const d of dirs) for(const f of walk(path.join(base,d))){ if(/\.(png|jpg)$/.test(f)||/desktop-released|memory/.test(f)) continue; const t=fs.readFileSync(f,"latin1"); if(key && t.includes(key)) exact++; for(const m of t.matchAll(re)){ if(/^sk-or-***MASKED***[0-9a-f]{64}$/.test(m[0])) hex64++; const s=m[0].replace(/[A-Za-z]/g,"a").replace(/[0-9]/g,"9"); stats[s]=(stats[s]||0)+1 } }
console.log({exactKeyFiles:exact,hex64Shaped:hex64,shapes:stats})'

